-- ************************************** ACMECORP.SUPPLYCHAIN.CUSTOMER_DT
CREATE DYNAMIC TABLE ACMECORP.SUPPLYCHAIN.CUSTOMER_DT
(
 ID,
 REGION,
 CREATED_AT
)
COMMENT = 'Dynamic table built from SUPPLYCHAIN.CUSTOMER with modified column mapping'
WAREHOUSE = DEMO_WH
TARGET_LAG = '10 MINUTES'
INITIALIZE = ON_CREATE
REFRESH_MODE = FULL
  AS SELECT 
    c.customerid AS id,             -- map CUSTOMERID → id
    c.country   AS region,          -- map COUNTRY → region
    CURRENT_TIMESTAMP AS created_at -- add system timestamp
FROM supplychain.customer c;
